using CGSmartK.Application;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace CGSmartK.Web.Controllers;[Authorize(Policy="KnowledgeAdministrator")]public sealed class AuditController(IAuditStore audit):Controller{public async Task<IActionResult> Index(string? correlationId,CancellationToken ct){ViewData["Status"]=string.IsNullOrWhiteSpace(correlationId)?null:await audit.GetAsync(correlationId,ct);return View();}}
